Here's an example of how you could write a basic debounce function using promises:

```javascript
function debounce(func, wait) {
  let timeout;
  return (...args) => {
    // Clear the interval if it exists and wait hasn't elapsed yet
    clearTimeout(timeout);

    timeout = setTimeout(() => {
      func.apply(this, args);
    }, wait);
  };
}

const myFunction = () => console.log('Processing...');

// Use the debounce function
const debouncedMyFunction = debounce(myFunction, 250);

debouncedMyFunction(); // Logs 'Processing...' after ~250ms
```

